#!/usr/bin/env bash
#
# Generates the boot splash from splash.svg (240 x 240, transparent around the
# drawing, which is shown on black) into:
# - splash.ppm: the kernel's boot logo, flattened on black, which fbcon draws in the
#   middle of the screen as soon as the display is up (external.mk puts it in the
#   kernel tree)
# - src/gen/splash_image.c: the PNG with its transparency, phone-ui's first frame at the
#   same place over black (splash.c), the same pixels; then it fades into the home
#   screen. Transparent, so that the drawing alone fades over the black.
#
# The kernel's logo takes at most 224 colors: flat colors and their antialiased
# edges stay well below. The script fails above rather than quantize, which would
# make the two differ.
#
# After running it: `just make linux-rebuild phone-ui-rebuild all`, then flash.
#
# Run in `nix develop` (resvg, ImageMagick):
#   external/package/phone-ui/gen-splash.sh
#

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

resvg "$here/splash.svg" "$tmp/splash.png"
magick "$tmp/splash.png" -background black -alpha remove -alpha off "$tmp/flat.png"
colors=$(magick "$tmp/flat.png" -format %k info:)
if [ "$colors" -gt 224 ]; then
	echo "splash.svg: $colors colors on black, the kernel's logo takes 224 at most" >&2
	exit 1
fi
magick "$tmp/flat.png" -depth 8 -compress none "ppm:$here/splash.ppm" # ASCII: the kernel reads no other

{
	echo "/* Generated by gen-splash.sh from splash.svg, do not edit */"
	echo
	echo "#include \"ui.h\""
	echo
	echo "const uint8_t ui_splash_png[] = {"
	od -An -v -tx1 "$tmp/splash.png" | sed -e 's/ \([0-9a-f][0-9a-f]\)/0x\1, /g' -e 's/ *$//' -e 's/^/\t/'
	echo "};"
	echo "const unsigned ui_splash_png_size = sizeof(ui_splash_png);"
} > "$tmp/splash_image.c"
mv "$tmp/splash_image.c" "$here/src/gen/splash_image.c"
